	/**
	 * Default Constructor
	 */
    public TerminationService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new TerminationEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(TerminationRepository.class) );
		this.validator		= applicationContext.getBean(TerminationValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Termination
	 */
		public Termination createTermination( CreateTerminationCommand command ) {

		Termination entity = new Termination();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTerminationId( command.getTerminationId() );
            entity.setTerminationNumber( command.getTerminationNumber() );
            entity.setTerminationDate( command.getTerminationDate() );
            entity.setNotes( command.getNotes() );
            entity.setEligibleForRehire( command.getEligibleForRehire() );
            entity.setReason( command.getReason() );
            entity.setType( command.getType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Termination {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateTerminationCommand
	 * @return		Termination
	 */
	public Termination updateTermination( UpdateTerminationCommand command ) {

		Termination entity = new Termination();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setTerminationId( command.getTerminationId() );
            entity.setTerminationNumber( command.getTerminationNumber() );
            entity.setTerminationDate( command.getTerminationDate() );
            entity.setNotes( command.getNotes() );
            entity.setEligibleForRehire( command.getEligibleForRehire() );
            entity.setEmployee( command.getEmployee() );
            entity.setAssignment( command.getAssignment() );
            entity.setReason( command.getReason() );
            entity.setType( command.getType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Termination {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteTerminationCommand
	 */
	public void delete( DeleteTerminationCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getTerminationId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Termination {0} ", id );

	}

	/**
	 * Method to retrieve the Termination via TerminationFetchOneSummary
	 * @param 	summary TerminationFetchOneSummary
	 * @return 	TerminationFetchOneResponse
	 */
	public Termination getTermination( TerminationFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TerminationFetchOneSummary arg cannot be null" );

		Termination entity = null;
		UUID id = summary.getTerminationId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Termination using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Terminations
	 *
	 * @return 	List<Termination>
	 */
    public List<Termination> getAllTermination() {
		List<Termination> list = projector.findAll( new FindAllTerminationQuery() );
		return list;
	}

	/**
	 * assign Employee on Termination
	 * @param		command AssignEmployeeToTerminationCommand
	 */
	public void assignEmployee( AssignEmployeeToTerminationCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignEmployee(command.getTerminationId(), command.getAssignment());

	}

	/**
	 * unAssign Employee on Termination
	 * @param		command UnAssignEmployeeFromTerminationCommand
	 */
	public void unAssignEmployee( UnAssignEmployeeFromTerminationCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignEmployee(command.getTerminationId());
	}
	
